186→func PatchSettings(t *testing.T, dir string, extra map[string]any) {
187→	t.Helper()
188→	path := filepath.Join(dir, ".entire", "settings.json")
189→	data, err := os.ReadFile(path)
190→	if err != nil {
191→		t.Fatalf("read settings: %v", err)
192→	}
