216→// IsSetUp returns true if Entire has been set up in the current repository.
217→// This checks if .entire/settings.json exists.
218→// Use this to avoid creating files/directories in repos where Entire was never enabled.
219→func IsSetUp() bool {
220→	settingsFileAbs, err := paths.AbsPath(EntireSettingsFile)
221→	if err != nil {
222→		return false
223→	}
224→	_, err = os.Stat(settingsFileAbs)
225→	return err == nil
226→}
