228→// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
229→// This checks if .entire/settings.json exists AND has enabled: true.
230→// Use this for hooks that should be no-ops when Entire is not active.
231→func IsSetUpAndEnabled() bool {
232→	if !IsSetUp() {
233→		return false
234→	}
235→	s, err := Load()
236→	if err != nil {
237→		return false
238→	}
239→	return s.Enabled
