242→// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
243→// Returns false by default if settings cannot be loaded or the key is missing.
244→func IsSummarizeEnabled() bool {
245→	settings, err := Load()
246→	if err != nil {
