252→// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
253→func (s *EntireSettings) IsSummarizeEnabled() bool {
254→	if s.StrategyOptions == nil {
255→		return false
256→	}
257→	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
258→	if !ok {
259→		return false
260→	}
261→	enabled, ok := summarizeOpts["enabled"].(bool)
262→	if !ok {
263→		return false
264→	}
265→	return enabled
266→}
