268→// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
269→// Returns true if push_sessions is explicitly set to false.
270→func (s *EntireSettings) IsPushSessionsDisabled() bool {
271→	if s.StrategyOptions == nil {
272→		return false
273→	}
274→	val, exists := s.StrategyOptions["push_sessions"]
275→	if !exists {
276→		return false
277→	}
278→	if boolVal, ok := val.(bool); ok {
279→		return !boolVal // disabled = !push_sessions
280→	}
281→	return false
282→}
