294→// saveToFile saves settings to the specified file path.
295→func saveToFile(settings *EntireSettings, filePath string) error {
296→	// Get absolute path for the file
297→	filePathAbs, err := paths.AbsPath(filePath)
298→	if err != nil {
299→		filePathAbs = filePath // Fallback to relative
300→	}
301→
302→	// Ensure directory exists
303→	dir := filepath.Dir(filePathAbs)
304→	if err := os.MkdirAll(dir, 0o750); err != nil {
305→		return fmt.Errorf("creating settings directory: %w", err)
306→	}
307→
308→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
309→	if err != nil {
310→		return fmt.Errorf("marshaling settings: %w", err)
311→	}
312→
313→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
314→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
315→		return fmt.Errorf("writing settings file: %w", err)
316→	}
317→	return nil
318→}
