704→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
705→// If strategyName is provided, it sets the strategy; otherwise uses default.
706→func setupAgentHooksNonInteractive(w io.Writer, ag agent.Agent, strategyName string, localDev, forceHooks, skipPushSessions, telemetry bool) error {
707→	agentName := ag.Name()
708→	// Check if agent supports hooks
709→	hookAgent, ok := ag.(agent.HookSupport)
710→	if !ok {
711→		return fmt.Errorf("agent %s does not support hooks", agentName)
712→	}
713→
714→	fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
715→
716→	// Install agent hooks (agent hooks don't depend on settings)
717→	installedHooks, err := hookAgent.InstallHooks(localDev, forceHooks)
718→	if err != nil {
719→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
720→	}
721→
722→	// Setup .entire directory
723→	if _, err := setupEntireDirectory(); err != nil {
724→		return fmt.Errorf("failed to setup .entire directory: %w", err)
725→	}
726→
727→	// Load existing settings to preserve other options (like strategy_options.push)
728→	settings, err := LoadEntireSettings()
729→	if err != nil {
730→		// If we can't load, start with defaults
731→		settings = &EntireSettings{Strategy: strategy.DefaultStrategyName}
732→	}
733→	settings.Enabled = true
734→	if localDev {
735→		settings.LocalDev = localDev
736→	}
737→
738→	// Set push_sessions option if --skip-push-sessions flag was provided
739→	if skipPushSessions {
740→		if settings.StrategyOptions == nil {
741→			settings.StrategyOptions = make(map[string]interface{})
742→		}
743→		settings.StrategyOptions["push_sessions"] = false
744→	}
745→
746→	// Set strategy if provided
747→	if strategyName != "" {
748→		// Map display name to internal name if needed
749→		internalStrategy := strategyName
750→		if mapped, ok := strategyDisplayToInternal[strategyName]; ok {
751→			internalStrategy = mapped
752→		}
753→		// Validate the strategy exists
754→		if _, err := strategy.Get(internalStrategy); err != nil {
755→			return fmt.Errorf("unknown strategy: %s (use manual-commit or auto-commit)", strategyName)
756→		}
757→		settings.Strategy = internalStrategy
758→	}
759→
760→	// Handle telemetry for non-interactive mode
761→	// Note: if telemetry is nil (not configured), it defaults to disabled
762→	if !telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
763→		f := false
764→		settings.Telemetry = &f
765→	}
766→
767→	if err := SaveEntireSettings(settings); err != nil {
768→		return fmt.Errorf("failed to save settings: %w", err)
769→	}
770→
771→	if _, err := strategy.InstallGitHook(true, localDev); err != nil {
772→		return fmt.Errorf("failed to install git hooks: %w", err)
773→	}
774→	strategy.CheckAndWarnHookManagers(w, localDev)
775→
776→	if installedHooks == 0 {
777→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
778→		if ag.IsPreview() {
779→			msg += " (Preview)"
780→		}
781→		fmt.Fprintf(w, "%s\n", msg)
782→	} else {
783→		msg := fmt.Sprintf("Installed %d hooks for %s", installedHooks, ag.Description())
784→		if ag.IsPreview() {
785→			msg += " (Preview)"
786→		}
787→		fmt.Fprintf(w, "%s\n", msg)
788→	}
789→
790→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplayProject)
791→
792→	// Let the strategy handle its own setup requirements (creates entire/checkpoints/v1 branch, etc.)
793→	strat, err := strategy.Get(settings.Strategy)
794→	if err != nil {
795→		return fmt.Errorf("failed to get strategy: %w", err)
796→	}
797→	if err := strat.EnsureSetup(); err != nil {
798→		return fmt.Errorf("failed to setup strategy: %w", err)
799→	}
800→
801→	fmt.Fprintln(w, "\nReady.")
802→
803→	return nil
804→}
