 98→			// Pattern lost — reset
 99→			matchedAt = time.Time{}
100→			lastStable = ""
101→			time.Sleep(500 * time.Millisecond)
102→			continue
103→		}
104→
105→		// Detect content change since Send was called
106→		if !contentChanged && stable != s.stableAtSend {
107→			contentChanged = true
108→		}
109→
110→		if stable != lastStable {
111→			// Pattern matches but content is still changing — reset settle timer
112→			matchedAt = time.Now()
113→			lastStable = stable
114→			time.Sleep(500 * time.Millisecond)
115→			continue
116→		}
117→
118→		// Pattern matches and content hasn't changed since matchedAt.
119→		// Only settle if content changed at least once after Send
120→		// (prevents false settle on echoed input before agent starts).
121→		if contentChanged && time.Since(matchedAt) >= settleTime {
122→			return content, nil
123→		}
124→
125→		time.Sleep(500 * time.Millisecond)
126→	}
127→	content := s.Capture()
128→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
129→}
