  6→	"regexp"
  7→	"strings"
  8→	"time"
  9→)
 10→
 11→// TmuxSession implements Session using tmux for PTY-based interactive agents.
 12→type TmuxSession struct {
 13→	name         string
 14→	stableAtSend string // stable content snapshot when Send was last called
 15→}
 16→
 17→// NewTmuxSession creates a new tmux session running the given command in dir.
 18→// unsetEnv lists environment variable names to strip from the session.
 19→func NewTmuxSession(name string, dir string, unsetEnv []string, command string, args ...string) (*TmuxSession, error) {
 20→	s := &TmuxSession{name: name}
 21→
 22→	tmuxArgs := []string{"new-session", "-d", "-s", name, "-c", dir}
 23→	// Build the shell command, prefixed with env -u for each var to strip.
 24→	shellCmd := ""
 25→	var shellCmdSb25 strings.Builder
 26→	for _, v := range unsetEnv {
 27→		shellCmdSb25.WriteString("env -u " + v + " ")
 28→	}
 29→	shellCmd += shellCmdSb25.String()
 30→	shellCmd += command
 31→	var shellCmdSb29 strings.Builder
 32→	for _, a := range args {
 33→		shellCmdSb29.WriteString(" " + a)
 34→	}
 35→	shellCmd += shellCmdSb29.String()
 36→	tmuxArgs = append(tmuxArgs, shellCmd)
 37→
 38→	cmd := exec.Command("tmux", tmuxArgs...)
 39→	if out, err := cmd.CombinedOutput(); err != nil {
 40→		return nil, fmt.Errorf("tmux new-session: %w\n%s", err, out)
 41→	}
 42→	// Keep the pane around after the command exits so we can capture error output.
 43→	setCmd := exec.Command("tmux", "set-option", "-t", name, "remain-on-exit", "on")
 44→	_ = setCmd.Run()
 45→	return s, nil
 46→}
 47→
 48→func (s *TmuxSession) Send(input string) error {
 49→	s.stableAtSend = stableContent(s.Capture())
 50→	// Send text and Enter separately — Claude's TUI can swallow Enter
 51→	// if it arrives before the input handler finishes processing the text.
 52→	if err := s.SendKeys(input); err != nil {
 53→		return err
 54→	}
 55→	time.Sleep(200 * time.Millisecond)
 56→	return s.SendKeys("Enter")
 57→}
 58→
 59→// SendKeys sends raw tmux key names without appending Enter.
 60→func (s *TmuxSession) SendKeys(keys ...string) error {
 61→	args := append([]string{"send-keys", "-t", s.name}, keys...)
 62→	cmd := exec.Command("tmux", args...)
 63→	out, err := cmd.CombinedOutput()
 64→	if err != nil {
 65→		return fmt.Errorf("tmux send-keys: %w\n%s", err, out)
 66→	}
 67→	return nil
 68→}
 69→
 70→const settleTime = 2 * time.Second
 71→
 72→// stableContent returns the content with the last few lines stripped,
 73→// so that TUI status bar updates don't prevent the settle timer.
 74→func stableContent(content string) string {
 75→	lines := strings.Split(content, "\n")
 76→	if len(lines) > 3 {
 77→		lines = lines[:len(lines)-3]
 78→	}
 79→	return strings.Join(lines, "\n")
 80→}
 81→
 82→func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
 83→	re, err := regexp.Compile(pattern)
 84→	if err != nil {
 85→		return "", fmt.Errorf("invalid pattern: %w", err)
 86→	}
 87→
 88→	deadline := time.Now().Add(timeout)
 89→	var matchedAt time.Time
 90→	var lastStable string
 91→	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
 92→
 93→	for time.Now().Before(deadline) {
 94→		content := s.Capture()
 95→		stable := stableContent(content)
 96→
 97→		if !re.MatchString(content) {
 98→			// Pattern lost — reset
 99→			matchedAt = time.Time{}
100→			lastStable = ""
101→			time.Sleep(500 * time.Millisecond)
102→			continue
103→		}
104→
105→		// Detect content change since Send was called
106→		if !contentChanged && stable != s.stableAtSend {
107→			contentChanged = true
108→		}
109→
110→		if stable != lastStable {
111→			// Pattern matches but content is still changing — reset settle timer
112→			matchedAt = time.Now()
113→			lastStable = stable
114→			time.Sleep(500 * time.Millisecond)
115→			continue
116→		}
117→
118→		// Pattern matches and content hasn't changed since matchedAt.
119→		// Only settle if content changed at least once after Send
120→		// (prevents false settle on echoed input before agent starts).
121→		if contentChanged && time.Since(matchedAt) >= settleTime {
122→			return content, nil
123→		}
124→
125→		time.Sleep(500 * time.Millisecond)
126→	}
127→	content := s.Capture()
128→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
129→}
130→
131→func (s *TmuxSession) Capture() string {
132→	cmd := exec.Command("tmux", "capture-pane", "-t", s.name, "-p")
133→	out, _ := cmd.Output()
134→	return strings.TrimRight(string(out), "\n")
135→}
136→
137→func (s *TmuxSession) Close() error {
138→	cmd := exec.Command("tmux", "kill-session", "-t", s.name)
139→	out, err := cmd.CombinedOutput()
140→	if err != nil {
141→		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
142→	}
143→	return nil
144→}
