 19→// RepoState holds the working state for a single test's cloned repository.
 20→type RepoState struct {
 21→	Agent            agents.Agent
 22→	Dir              string
 23→	ArtifactDir      string
 24→	HeadBefore       string
 25→	CheckpointBefore string
 26→	ConsoleLog       *os.File
 27→}
 28→
 29→// SetupRepo creates a fresh git repository in a temporary directory, seeds it
 30→// with an initial commit, and runs `entire enable` for the given agent.
 31→// Artifact capture is registered as a cleanup function.
 32→//
 33→// When E2E_KEEP_REPOS is set, the temporary directory is not cleaned up
 34→// so it can be inspected after the test. A symlink in the artifact dir
 35→// points to the preserved repo.
 36→func SetupRepo(t *testing.T, agent agents.Agent) *RepoState {
 37→	t.Helper()
 38→
 39→	keepRepos := os.Getenv("E2E_KEEP_REPOS") != ""
 40→
 41→	// Always use os.MkdirTemp instead of t.TempDir(). Go's t.TempDir()
 42→	// creates nested subdirectories (TestName.../001/) whose structure
 43→	// confuses some agents' (e.g. opencode) working-directory resolution.
 44→	dir, err := os.MkdirTemp("", "e2e-repo-*")
 45→	if err != nil {
 46→		t.Fatalf("create temp dir: %v", err)
 47→	}
 48→	if keepRepos {
 49→		t.Logf("E2E_KEEP_REPOS: repo will be preserved at %s", dir)
 50→	} else {
 51→		t.Cleanup(func() { os.RemoveAll(dir) })
 52→	}
 53→
 54→	// Resolve symlinks (macOS: /var -> /private/var) so paths match
 55→	// what agent CLIs see when they resolve their own CWD.
 56→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
 57→		dir = resolved
 58→	}
 59→
 60→	Git(t, dir, "init")
 61→	Git(t, dir, "config", "user.name", "E2E Test")
 62→	Git(t, dir, "config", "user.email", "e2e@test.local")
 63→	Git(t, dir, "commit", "--allow-empty", "-m", "initial commit")
 64→
 65→	entire.Enable(t, dir, agent.EntireAgent(), "")
 66→	PatchSettings(t, dir, map[string]any{"log_level": "debug"})
 67→
 68→	// OpenCode's non-interactive mode auto-rejects external_directory permission
 69→	// since there's no user to prompt. Write a config to allow it.
 70→	if agent.Name() == "opencode" {
 71→		cfg := `{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}}`
 72→		if key := os.Getenv("ANTHROPIC_API_KEY"); key != "" {
 73→			cfg = fmt.Sprintf(`{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}, "provider": {"anthropic": {"options": {"apiKey": %q}}}}`, key)
 74→		}
 75→		if err := os.WriteFile(filepath.Join(dir, "opencode.json"), []byte(cfg+"\n"), 0o644); err != nil {
 76→			t.Fatalf("write opencode.json: %v", err)
 77→		}
 78→	}
 79→
 80→	// Create artifact dir eagerly so console.log is written to disk
 81→	// incrementally. Even if the test is killed by a global timeout,
 82→	// partial output survives.
 83→	artDir := artifactDir(t)
 84→	consoleLog, err := os.Create(filepath.Join(artDir, "console.log"))
 85→	if err != nil {
 86→		t.Fatalf("create console.log: %v", err)
 87→	}
 88→
 89→	state := &RepoState{
 90→		Agent:            agent,
 91→		Dir:              dir,
 92→		ArtifactDir:      artDir,
 93→		HeadBefore:       GitOutput(t, dir, "rev-parse", "HEAD"),
 94→		CheckpointBefore: GitOutput(t, dir, "rev-parse", "entire/checkpoints/v1"),
 95→		ConsoleLog:       consoleLog,
 96→	}
 97→
 98→	t.Cleanup(func() {
 99→		_ = consoleLog.Close()
100→		CaptureArtifacts(t, state)
101→	})
102→
103→	return state
104→}
