106→// ForEachAgent runs fn as a parallel subtest for every registered agent.
107→// It handles repo setup, concurrency gating, context timeout, and cleanup.
108→// The timeout is scaled by each agent's TimeoutMultiplier.
109→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
110→	t.Helper()
111→	t.Parallel()
112→	for _, agent := range agents.All() {
113→		t.Run(agent.Name(), func(t *testing.T) {
114→			s := SetupRepo(t, agent)
115→
116→			// Use the global test deadline for slot wait so we don't
117→			// skip prematurely — only bail if the whole binary is dying.
118→			slotCtx := context.Background()
119→			if deadline, ok := t.Deadline(); ok {
120→				var cancel context.CancelFunc
121→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
122→				defer cancel()
123→			}
124→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
125→				t.Fatalf("timed out waiting for agent slot: %v", err)
126→			}
127→			defer agents.ReleaseSlot(agent)
128→
129→			// Per-test timeout starts after slot is acquired, scaled
130→			// by the agent's multiplier (e.g. 2.5× for gemini).
131→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
132→			ctx, cancel := context.WithTimeout(context.Background(), scaled)
133→			defer cancel()
134→			fn(t, s, ctx)
135→		})
136→	}
137→}
