139→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
140→// and returns the result. If the agent reports a transient API error, the
141→// prompt is retried once after a short delay. The caller should still check err.
142→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
143→	t.Helper()
144→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
145→	s.logPromptResult(out)
146→
147→	if err != nil && s.Agent.IsTransientError(out, err) {
148→		t.Logf("transient API error detected, retrying in 5s: %v", err)
149→		s.ConsoleLog.WriteString("> [retry] transient error, waiting 5s...\n")
150→		select {
151→		case <-time.After(5 * time.Second):
152→		case <-ctx.Done():
153→			return out, err
154→		}
155→		out, err = s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
156→		s.logPromptResult(out)
157→	}
158→
159→	return out, err
160→}
