332→	deadline := time.Now().Add(timeout)
333→	for time.Now().Before(deadline) {
334→		raw := gitOutputSafe(dir, "show", blob)
335→		if raw != "" {
336→			var meta SessionMetadata
337→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
338→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
339→			}
340→			return meta
341→		}
342→		time.Sleep(500 * time.Millisecond)
343→	}
344→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
345→	return SessionMetadata{}
